:root {
  --bg: #1b1f2a;
  --card: #262c3a;
  --ink: #eef2f7;
  --muted: #9aa6b8;
  --accent: #4ade80;
  --accent-dark: #22a35a;
  --danger: #ef4444;
  --focus: #facc15;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: radial-gradient(circle at 50% 0%, #2a3245 0%, var(--bg) 70%);
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
}

.game-card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border-radius: 18px;
  padding: 24px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45), inset 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.game-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

h1 {
  font-size: 1.5rem;
  margin: 0;
  letter-spacing: 0.02em;
}

.score-line {
  margin: 0;
  font-size: 1rem;
  color: var(--muted);
}

#score {
  color: var(--accent);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.board-wrap {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  background: #12161f;
  border: 2px solid #333c4e;
}

#board {
  display: block;
  width: 100%;
  height: auto;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 20px;
  background: rgba(18, 22, 31, 0.88);
  backdrop-filter: blur(2px);
}

.overlay.hidden { display: none; }

.overlay h2 {
  margin: 0 0 8px;
  font-size: 1.25rem;
  color: var(--accent);
}

.overlay p {
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.5;
  color: var(--ink);
  max-width: 34ch;
}

.controls {
  display: flex;
  gap: 12px;
  margin-top: 18px;
}

.btn {
  flex: 1;
  font: inherit;
  font-weight: 600;
  padding: 12px 16px;
  border-radius: 10px;
  border: 2px solid #3a4459;
  background: #2f3748;
  color: var(--ink);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.05s ease, border-color 0.15s ease;
}

.btn:hover { background: #3a4459; border-color: #4a566e; }
.btn:active { transform: translateY(1px); background: #262c3a; }
.btn:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #0b1a10;
}

.btn-primary:hover { background: #5eea92; border-color: #5eea92; }
.btn-primary:active { background: var(--accent-dark); border-color: var(--accent-dark); }

.hint {
  margin: 14px 0 0;
  text-align: center;
  font-size: 0.85rem;
  color: var(--muted);
}

@media (max-width: 400px) {
  .game-card { padding: 16px; border-radius: 14px; }
  h1 { font-size: 1.25rem; }
  .controls { flex-direction: column; }
  .btn { width: 100%; }
}

(function () {
  "use strict";

  var canvas = document.getElementById("board");
  var ctx = canvas.getContext("2d");
  var scoreEl = document.getElementById("score");
  var overlay = document.getElementById("overlay");
  var overlayTitle = document.getElementById("overlay-title");
  var overlayText = document.getElementById("overlay-text");
  var startPauseBtn = document.getElementById("start-pause");
  var restartBtn = document.getElementById("restart");

  var GRID = 16;
  var CELL = canvas.width / GRID;
  var TICK_MS = 140;

  var snake, dir, nextDir, food, score, running, gameOver, timer;

  function reset() {
    clearInterval(timer);
    timer = null;
    snake = [{ x: 8, y: 8 }, { x: 7, y: 8 }, { x: 6, y: 8 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    running = false;
    gameOver = false;
    scoreEl.textContent = "0";
    placeFood();
    draw();
    showOverlay("How to Play", "Use the arrow keys to move. Eat the red food to grow and score. Avoid walls and yourself. Press Start or any arrow key to begin.");
    startPauseBtn.textContent = "Start";
  }

  function placeFood() {
    var free = [];
    for (var y = 0; y < GRID; y++) {
      for (var x = 0; x < GRID; x++) {
        if (!snake.some(function (s) { return s.x === x && s.y === y; })) {
          free.push({ x: x, y: y });
        }
      }
    }
    food = free.length ? free[Math.floor(Math.random() * free.length)] : null;
  }

  function showOverlay(title, text) {
    overlayTitle.textContent = title;
    overlayText.textContent = text;
    overlay.classList.remove("hidden");
  }

  function hideOverlay() {
    overlay.classList.add("hidden");
  }

  function draw() {
    ctx.fillStyle = "#12161f";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = "#1c2330";
    for (var y = 0; y < GRID; y++) {
      for (var x = 0; x < GRID; x++) {
        if ((x + y) % 2 === 0) {
          ctx.fillRect(x * CELL, y * CELL, CELL, CELL);
        }
      }
    }

    if (food) {
      ctx.fillStyle = "#ef4444";
      ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);
    }

    for (var i = 0; i < snake.length; i++) {
      var s = snake[i];
      ctx.fillStyle = i === 0 ? "#4ade80" : "#22a35a";
      ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
    }
  }

  function step() {
    dir = nextDir;
    var head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(function (s) { return s.x === head.x && s.y === head.y; })) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (food && head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function start() {
    if (gameOver) reset();
    running = true;
    hideOverlay();
    startPauseBtn.textContent = "Pause";
    clearInterval(timer);
    timer = setInterval(step, TICK_MS);
  }

  function pause() {
    if (!running) return;
    running = false;
    clearInterval(timer);
    timer = null;
    startPauseBtn.textContent = "Resume";
    showOverlay("Paused", "Press Resume, Space, or an arrow key to continue.");
  }

  function endGame() {
    running = false;
    gameOver = true;
    clearInterval(timer);
    timer = null;
    startPauseBtn.textContent = "Start";
    showOverlay("Game Over", "Final score: " + score + ". Press Restart or Start to play again.");
  }

  function toggle() {
    if (running) pause();
    else start();
  }

  function setDirection(nx, ny) {
    if (gameOver) return;
    if (nx === -dir.x && ny === -dir.y) return;
    nextDir = { x: nx, y: ny };
    if (!running) start();
  }

  document.addEventListener("keydown", function (e) {
    var key = e.key;
    if (key === "ArrowUp") { e.preventDefault(); setDirection(0, -1); }
    else if (key === "ArrowDown") { e.preventDefault(); setDirection(0, 1); }
    else if (key === "ArrowLeft") { e.preventDefault(); setDirection(-1, 0); }
    else if (key === "ArrowRight") { e.preventDefault(); setDirection(1, 0); }
    else if (key === " " || key === "Spacebar") { e.preventDefault(); toggle(); }
  });

  startPauseBtn.addEventListener("click", toggle);
  restartBtn.addEventListener("click", reset);

  reset();
})();
